      const fx = makeAgentEngine106({
        panelText: PROP22_12_106, permEnabled: true, aOpens: true,
        onSend: (state) => {
          if (state.sends === 2) { state.panelText = PROP30_106; state.groupText = PROP30_106; state.permEnabled = true; }
        }
      });
