    eq('X106 batch-DB: row indexes are 0,1,2', JSON.stringify(rt106 && rt106.idx), JSON.stringify([0, 1, 2]));
    try { fs106b.rmSync(tmpDir106, { recursive: true, force: true }); } catch (e) {}
